export const crmActivitiesComplete = (
  id: string,
  options?: SecondParameter<typeof apiClient>,
  signal?: AbortSignal,
) => {
  return apiClient<ActivityDto>(
    { url: `/api/v1/crm-activities/${id}/complete`, method: 'POST', signal },
    options,
  );
};

export const getCrmActivitiesCompleteMutationKey = () => ['crmActivitiesComplete'] as const;

export const getCrmActivitiesCompleteMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof crmActivitiesComplete>>,
    TError,
    CrmActivitiesCompleteMutationVariables,
    TContext
  >;
  request?: SecondParameter<typeof apiClient>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof crmActivitiesComplete>>,
  TError,
  CrmActivitiesCompleteMutationVariables,
  TContext
> => {
  const mutationKey = getCrmActivitiesCompleteMutationKey();
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof crmActivitiesComplete>>,
    CrmActivitiesCompleteMutationVariables
  > = (props) => {
    const { id } = props ?? {};

    return crmActivitiesComplete(id, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type CrmActivitiesCompleteMutationResult = NonNullable<
  Awaited<ReturnType<typeof crmActivitiesComplete>>
>;

export type CrmActivitiesCompleteMutationError = ErrorType<unknown>;
export type CrmActivitiesCompleteMutationVariables = { id: string };

